<?php
require_once __DIR__ . '/_bootstrap.php';
$term=trim((string)($_GET['tracking']??'')); $rows=[];
if($term!=='') $rows=logisticsRows('SELECT * FROM shipments WHERE tracking_number=? LIMIT 1',[$term]);
$shipment=$rows[0]??null; $events=$shipment?logisticsRows('SELECT * FROM shipment_tracking WHERE shipment_id=? ORDER BY created_at DESC',[(int)$shipment['id']]):[];
logisticsPage('Track shipment','tracking.php'); ?>
<section class="lx-card"><h2>Global shipment tracking</h2><form class="lx-filter" method="get"><input name="tracking" value="<?=e($term)?>" placeholder="Enter tracking number" required><button class="lx-btn">Track shipment</button></form><?php if($term && !$shipment): ?><div class="lx-alert">We couldn't find that tracking number. Check the reference and try again.</div><?php elseif($shipment): ?><div class="lx-detail"><div><p class="lx-eyebrow">TRACKING REFERENCE</p><h2><?=e(logisticsValue($shipment,['tracking_number','tracking_code']))?></h2><span class="lx-badge"><?=e(logisticsStatus(logisticsValue($shipment,['status'],'pending')))?></span><p><?=e(logisticsValue($shipment,['destination','delivery_address','city']))?></p></div><ul class="lx-timeline"><?php if(!$events): ?><li><div><strong>Shipment registered</strong><small>Awaiting the first carrier scan.</small></div></li><?php else: foreach($events as $event): ?><li><div><strong><?=e(logisticsStatus(logisticsValue($event,['status','event','title'],'Update')))?></strong><small><?=e(logisticsValue($event,['location','description']))?><br><?=e(logisticsValue($event,['created_at','event_time']))?></small></div></li><?php endforeach; endif; ?></ul></div><?php else: ?><div class="lx-empty">Enter a tracking number to see the latest movement and delivery milestones.</div><?php endif; ?></section>
<?php logisticsEnd(); ?>
